import wave,numpy as np
p='/workspace/preview2.wav';w=wave.open(p,'rb');x=np.frombuffer(w.readframes(w.getnframes()),dtype=np.int16).reshape(-1,2); sr=w.getframerate();print('frames',len(x),'secs',len(x)/sr)
# compare by seam; derive from render one length given prior exact 70.217142857
L=int(round(70.217142857*sr));print('loopframes',L,'seam',L,len(x));
# Blocks around seam RMS and peak
for a,b in [(L-22050,L),(L,L+22050),(L-100,L+100),(L-2205,L),(L,L+2205)]:
 z=x[a:b].astype(float); print(a,b,'rms',np.sqrt(np.mean(z*z)),'peak',np.max(np.abs(z)))
# at seam compare waveform chunks offset by loop length; exact samples maybe repeated except voice state?
for dur in [0.05,.1,.25,.5,1.0]:
 n=int(dur*sr);u=x[L-n:L].astype(float);v=x[L:L+n].astype(float);print('cross',dur,'rms prev,next',np.std(u),np.std(v),'corr',np.corrcoef(u.reshape(-1),v.reshape(-1))[0,1], 'dc',np.mean(u),np.mean(v))
PY"}

